      "ko": "지진·태풍·화재·교통사고를 실제처럼 겪어 보는 무료 안전 체험관. 소방관과 함께 방수 체험을 하고 2019년생부터 화재·지진 프로그램에 들어갈 수 있습니다. 1층 소방역사박물관은 예약 없이 관람합니다.",
